const state={auth:null,appStarted:false,page:'dashboard',certStatus:'',employeeData:[],trainingData:[],trainingEmployees:[],historyData:[],certData:[],compData:[],assessmentData:[],validationData:[],defs:{},refs:{positions:[],training:[],certifications:[]},trainingFilters:{employee:'',position:'',department:'',type:''},safeImportBatch:null,actions:[],actionMeta:{statuses:[],types:[],priorities:[]},picUsers:[],notifications:[],profile:null,profileTab:'overview',globalSearchTimer:null,analytics:null,analyticsDepartments:[],aiConversationId:(globalThis.crypto?.randomUUID?globalThis.crypto.randomUUID():String(Date.now()))};
const trainingDetailMap=new Map();
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tag=v=>{const s=String(v||'').toLowerCase();let cls='tag-blue';if(s.includes('expired')||s.includes('gap'))cls='tag-red';else if(s.includes('validation')||s.includes('near')||s.includes('process'))cls='tag-amber';else if(s.includes('covered')||s.includes('active'))cls='tag-green';return `<span class="tag ${cls}">${esc(v||'—')}</span>`};
async function api(path,opts={}){opts.headers=opts.headers||{};const r=await fetch(path,opts);const text=await r.text();let data={};try{data=text?JSON.parse(text):{}}catch{data=text}if(!r.ok){const detail=(data&&data.detail)||text||`HTTP ${r.status}`;if(r.status===401&&!path.includes('/api/auth/login'))showLoginScreen();if(r.status===403&&detail==='PASSWORD_CHANGE_REQUIRED')showPasswordScreen();throw new Error(detail)}return data}
function can(permission){return !!state.auth?.user?.permissions?.includes(permission)}
function authRoleLabel(){return state.auth?.role_label||state.auth?.user?.role||'—'}
function applyPermissionUI(){const hide=(id,p)=>document.getElementById(id)?.classList.toggle('permission-hidden',!can(p));hide('system-nav','backup_manage');hide('training-catalog-add-btn','requirement_manage');hide('requirement-add-btn','requirement_manage');hide('action-add-btn','action_manage');hide('analytics-snapshot-btn','system_write');document.querySelectorAll('[data-crud="requirement"]').forEach(x=>x.classList.toggle('permission-hidden',!can('requirement_manage')));document.getElementById('auth-user-name').textContent=state.auth?.user?.display_name||'—';document.getElementById('auth-user-role').textContent=authRoleLabel();const ac=document.getElementById('assessment-role-copy');if(ac)ac.innerHTML=can('assessment_manage')?'Kelola lifecycle assessment: <strong>Pending Initial Assessment → Assessment Ready → Assessed</strong>, serta <strong>Pending Reassessment → Assessed</strong> ketika evidence atau kebutuhan berubah.':'Pantau lifecycle assessment secara read-only. Initial Assessment dan Reassessment merupakan tindakan <strong>Supervisor TCD</strong>.';const vc=document.getElementById('validation-role-copy');if(vc)vc.innerHTML=can('validation_manage')?'Human validation untuk mapping/evidence yang belum cukup pasti. Validator memberikan keputusan dan evidence; Decision Engine tetap menghitung ulang status.':'Pantau mapping/evidence yang masih memerlukan validasi TCD. Role ini memiliki akses <strong>read-only</strong> terhadap Validation Queue.'}
function showLoginScreen(){document.getElementById('password-screen')?.classList.add('hidden');document.getElementById('login-screen')?.classList.remove('hidden');state.auth=null}
function hideLoginScreens(){document.getElementById('login-screen')?.classList.add('hidden');document.getElementById('password-screen')?.classList.add('hidden')}
function showPasswordScreen(){document.getElementById('login-screen')?.classList.add('hidden');document.getElementById('password-screen')?.classList.remove('hidden')}
async function handleLogin(e){e.preventDefault();const btn=document.getElementById('login-button'),err=document.getElementById('login-error');btn.disabled=true;err.classList.add('hidden');try{const d=await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.getElementById('login-username').value.trim(),password:document.getElementById('login-password').value})});state.auth=d;applyPermissionUI();if(d.user?.must_change_password){showPasswordScreen()}else{hideLoginScreens();startApp()}}catch(ex){err.textContent=ex.message;err.classList.remove('hidden')}finally{btn.disabled=false}}
async function handlePasswordChange(e){e.preventDefault();const err=document.getElementById('password-error'),np=document.getElementById('new-password').value,cp=document.getElementById('confirm-password').value;err.classList.add('hidden');if(np!==cp){err.textContent='Konfirmasi password baru tidak sama.';err.classList.remove('hidden');return}try{await jsonApi('/api/auth/change-password','POST',{current_password:document.getElementById('current-password').value,new_password:np});showToast('Password berhasil diganti. Silakan login kembali.');document.getElementById('password-form').reset();showLoginScreen()}catch(ex){err.textContent=ex.message;err.classList.remove('hidden')}}
async function doLogout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}state.appStarted=false;showLoginScreen()}
async function openChangePassword(){showPasswordScreen()}
async function bootstrapAuth(){try{const d=await api('/api/auth/me');state.auth=d;applyPermissionUI();if(d.user?.must_change_password)showPasswordScreen();else{hideLoginScreens();startApp()}}catch{showLoginScreen()}}
function startApp(){if(state.appStarted)return;state.appStarted=true;applyPermissionUI();loadRefs().catch(()=>{});loadEmployees().catch(()=>{});refreshNotifications().catch(()=>{});goTo('dashboard')}
async function jsonApi(path,method,payload){return api(path,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})}
function goTo(page){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));const target=document.getElementById(page);if(!target)return;target.classList.add('active');document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.getElementById('page-title').textContent={dashboard:'Dashboard',employee:'Employee Management',training:'Training Explorer',history:'Training History',certification:'Certification Monitoring',competency:'Competency Explorer',assessment:'Assessment Queue',validation:'Validation Queue',actions:'Action Center',ai:'AI Assistant',analytics:'Reports & Management Analytics',data:'Data Management',system:'System & Backup'}[page]||page;state.page=page;if(page==='dashboard')loadDashboard();if(page==='employee')loadEmployees();if(page==='training')loadTraining();if(page==='history')loadHistory();if(page==='certification')loadCertification();if(page==='competency')loadCompetency();if(page==='assessment')loadAssessmentQueue();if(page==='validation')loadValidation();if(page==='actions')loadActions();if(page==='analytics')loadAnalytics();if(page==='data')loadData();if(page==='system')loadSystem();if(page==='ai')loadDefinitions('AI Assistant','ai-definitions');window.scrollTo({top:0,behavior:'smooth'})}
// Build v22.7 — Employee 360, operational dashboard, global search, exports
function currentExportFilters(dataset){
  const f={};
  if(dataset==='employees')f.search=document.getElementById('employee-search')?.value||'';
  if(dataset==='training_requirements'){
    f.search=document.getElementById('training-search')?.value||'';
    f.employee_pk=trainingEffectiveEmployeePk();
    f.position=document.getElementById('training-position-filter')?.value||'';
    f.department=document.getElementById('training-department-filter')?.value||'';
    f.requirement_type=document.getElementById('training-type-filter')?.value||'';
  }
  if(dataset==='training_history')f.search=document.getElementById('history-search')?.value||'';
  if(dataset==='certifications'){f.search=document.getElementById('cert-search')?.value||'';f.status=state.certStatus||''}
  if(dataset==='competency'){f.search=document.getElementById('comp-search')?.value||'';f.status=document.getElementById('competency-filter')?.value||''}
  if(dataset==='actions'){f.status=document.getElementById('action-status-filter')?.value||'';f.deleted=document.getElementById('action-deleted-filter')?.value||'active'}
  return f;
}
function downloadExport(dataset,filtered=true){const f=filtered?currentExportFilters(dataset):{};const p=new URLSearchParams();Object.entries(f).forEach(([k,v])=>{if(v!==undefined&&v!==null&&String(v).trim()!=='')p.set(k,String(v))});window.location.href=`/api/export/${encodeURIComponent(dataset)}?${p.toString()}`}
function closeEmployeeProfile(){const el=document.getElementById('employee-profile');el.classList.remove('open');el.setAttribute('aria-hidden','true');state.profile=null}
async function openEmployeeProfile(id,tab='overview'){try{const d=await api(`/api/employees/${id}/profile`);state.profile=d;state.profileTab=tab;const e=d.employee,s=d.summary||{};document.getElementById('profile-name').textContent=e.employee_name;const assessmentTag=`<span class="tag tag-blue" title="Assessment telah dijalankan. Sebagian requirement dapat tetap berstatus Not Assessed jika evidence atau mapping belum cukup.">${esc(e.assessment_state||'—')}</span>`;document.getElementById('profile-meta').innerHTML=`<span>${esc(e.employee_code||'—')}</span><span>${esc(e.position_name||'No Position')}</span><span>${esc(e.department||'—')}</span>${tag(e.employment_status||'—')}${assessmentTag}`;document.getElementById('profile-summary').innerHTML=[['Requirements',s.requirements||0],['Training History',s.training_history||0],['Certifications',s.certifications||0],['Covered',s.covered||0],['Potential Gap',s.potential_gap||0],['Validation',s.validation_required||0],['Not Assessed',s.not_assessed||0],['Open Actions',s.open_actions||0]].map(([l,v])=>`<div><span>${esc(l)}</span><strong>${esc(v)}</strong></div>`).join('');document.querySelectorAll('[data-profile-tab]').forEach(b=>b.classList.toggle('active',b.dataset.profileTab===tab));renderEmployeeProfileTab(tab);const el=document.getElementById('employee-profile');el.classList.add('open');el.setAttribute('aria-hidden','false')}catch(e){showToast(e.message,'error')}}
function profileTable(headers,rows){return `<div class="table-wrap profile-table"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}">No data.</td></tr>`}</tbody></table></div>`}
function profileAttentionRows(){const d=state.profile;return (d.requirements||[]).filter(x=>x.coverage_status&&x.coverage_status!=='Covered').slice(0,12)}
function renderEmployeeProfileTab(tab){state.profileTab=tab;const d=state.profile;if(!d)return;const e=d.employee,c=document.getElementById('profile-content');document.querySelectorAll('[data-profile-tab]').forEach(b=>b.classList.toggle('active',b.dataset.profileTab===tab));
 if(tab==='overview'){const att=profileAttentionRows();c.innerHTML=`<div class="profile-grid"><div class="profile-panel"><div class="panel-head"><h3>Current Attention</h3>${can('action_manage')?`<button class="mini-btn" onclick="openActionCreate({employee_pk:${Number(e.employee_pk)}})">+ Action</button>`:''}</div>${att.length?att.map(x=>`<div class="profile-attention"><div><strong>${esc(x.training_name)}</strong><span>${tag(x.coverage_status)} ${tag(x.priority||'—')}</span></div><button class="mini-btn" onclick="goProfileRequirement(${Number(x.requirement_id)})">View Detail</button></div>`).join(''):'<div class="empty-state"><strong>No current assessment attention</strong><span>Covered or assessment data is not yet available.</span></div>'}</div><div class="profile-panel"><h3>Employee Information</h3><div class="info-list"><div><span>Join Date</span><strong>${esc(e.join_date||'—')}</strong></div><div><span>Assessment State</span><strong title="Assessment telah dijalankan; ini tidak berarti semua requirement sudah Covered.">${esc(e.assessment_state||'—')}</strong></div><div><span>Last Assessment</span><strong>${esc(e.last_assessment_at||'—')}</strong></div><div><span>Status Reason</span><strong>${esc(e.status_reason||'—')}</strong></div><div class="wide"><span>Remarks</span><strong>${esc(e.remarks||'—')}</strong></div></div></div></div>`}
 else if(tab==='training'){const reqRows=(d.requirements||[]).map(x=>`<tr><td>${esc(x.training_name)}</td><td>${tag(x.requirement_type)}</td><td>${tag(x.coverage_status||'Pending')}</td><td>${tag(x.priority||'—')}</td></tr>`).join('');const hist=(d.training||[]).map(x=>`<tr><td>${esc(x.training_name)}</td><td>${esc(x.completion_date||x.training_date||'—')}</td><td>${tag(x.result_status||'—')}</td><td>${esc(x.provider||'—')}</td><td>${esc(x.valid_until||'—')}</td></tr>`).join('');c.innerHTML=`<div class="profile-section-title"><div><h3>Training Requirement</h3><p>${(d.requirements||[]).length} applicable requirement</p></div><button class="primary" onclick="openHistoryCreate({employee_pk:${Number(e.employee_pk)}})">+ Add Training Record</button></div>${profileTable(['Training','Type','Coverage','Priority'],reqRows)}<div class="profile-section-title"><div><h3>Training History</h3><p>Actual training evidence</p></div></div>${profileTable(['Training','Date','Result','Provider','Valid Until'],hist)}`}
 else if(tab==='certification'){const rows=(d.certifications||[]).map(x=>`<tr><td><strong>${esc(x.certification_name_raw)}</strong><span class="sub">${esc(x.certificate_number||'')}</span></td><td>${tag(x.certification_status||'—')}</td><td>${esc(x.expiry_date||'—')}</td><td>${tag(x.renewal_status||'—')}</td><td><button class="mini-btn" onclick="profileRenew(${Number(x.certification_id)})">Renew</button></td></tr>`).join('');c.innerHTML=`<div class="profile-section-title"><div><h3>Certification</h3><p>Current and renewal records</p></div><button class="primary" onclick="openCertificationCreate({employee_pk:${Number(e.employee_pk)}})">+ Add Certification</button></div>${profileTable(['Certification','Status','Expiry','Renewal','Action'],rows)}`}
 else if(tab==='competency'){const rows=(d.competency||[]).map(x=>`<tr><td>${esc(x.training_name||x.requirement_training_name||'—')}</td><td>${tag(x.final_status||x.coverage_status||'—')}</td><td>${tag(x.priority||'—')}</td><td>${tag(x.assessment_source||'Legacy')}</td><td><button class="mini-btn" onclick="showDecisionReason(${Number(e.employee_pk)},${Number(x.requirement_id||0)})">Why?</button> ${can('action_manage')?`<button class="mini-btn" onclick="openActionFromCompetency(${Number(e.employee_pk)},${Number(x.requirement_id||0)})">Action</button>`:''}</td></tr>`).join('');c.innerHTML=`<div class="profile-section-title"><div><h3>Competency-related Assessment</h3><p>Requirement coverage; bukan direct competency score.</p></div></div>${profileTable(['Requirement','Coverage','Priority','Source','Action'],rows)}`}
 else if(tab==='actions'){const rows=(d.actions||[]).map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.action_type)}</td><td>${tag(x.priority)}</td><td>${esc(x.pic_name||'Unassigned')}</td><td>${esc(x.due_date||'—')}</td><td>${tag(x.status)}</td><td>${can('action_manage')?`<button class="mini-btn" onclick="openActionManage(${Number(x.action_id)})">Manage</button>`:'<span class="sub">View only</span>'}</td></tr>`).join('');c.innerHTML=`<div class="profile-section-title"><div><h3>Action & Follow-up</h3><p>Operational follow-up linked to this employee.</p></div>${can('action_manage')?`<button class="primary" onclick="openActionCreate({employee_pk:${Number(e.employee_pk)}})">+ Create Action</button>`:''}</div>${profileTable(['Action','Type','Priority','PIC','Due','Status',''],rows)}`}
 else if(tab==='documents'){const rows=(d.documents||[]).map(x=>`<tr><td>${esc(x.document_type)}</td><td>${esc(x.original_filename)}</td><td><strong>${esc(x.linked_label||x.entity_type||'—')}</strong><span class="sub">${esc(x.linked_context||'')}</span></td><td>${esc(x.uploaded_at)}${x.uploaded_by_name?`<span class="sub">by ${esc(x.uploaded_by_name)}</span>`:''}</td><td><div class="row-actions">${Number(x.viewable)?`<button class="mini-btn" onclick="window.open('/api/evidence/${Number(x.document_id)}/view','_blank')">View</button>`:''}<button class="mini-btn" onclick="window.location.href='/api/evidence/${Number(x.document_id)}/download'">Download</button></div></td></tr>`).join('');c.innerHTML=`<div class="profile-section-title"><div><h3>Evidence Documents</h3><p>Training, certification, validation, and action evidence.</p></div></div>${profileTable(['Type','File','Linked To','Uploaded',''],rows)}`}
 else if(tab==='history'){const rows=(d.timeline||[]).map(x=>`<div class="timeline-item"><div class="timeline-marker"></div><div><small>${esc(x.event_date||'—')} · ${esc(x.event_type)}${x.actor?` · by ${esc(x.actor)}`:''}</small><strong>${esc(x.title)}</strong><span>${esc(x.detail||'')}</span></div></div>`).join('');c.innerHTML=`<div class="profile-section-title"><div><h3>Employee History</h3><p>Position, training, certification, assessment, action, dan evidence timeline.</p></div></div><div class="timeline">${rows||'<div class="empty-state">No history yet.</div>'}</div>`}}
function goProfileRequirement(requirementId){const d=state.profile,e=d?.employee;if(!e)return;closeEmployeeProfile();goTo('competency');document.getElementById('comp-search').value=e.employee_name;loadCompetency()}
async function showDecisionReason(employeePk,requirementId){if(!requirementId){showToast('Decision trace belum tersedia untuk legacy record.','error');return}try{const d=await api(`/api/competency/${employeePk}/requirement/${requirementId}/decision-trace`);openCrud('Why this status?',[{name:'trace',label:'Decision Trace',type:'textarea',value:JSON.stringify(d,null,2),wide:true}],async()=>{}, {note:'Read-only explanation from Decision Engine evidence trace.',submit:'Close'});document.getElementById('crud-submit').type='button';document.getElementById('crud-submit').onclick=closeCrud}catch(e){showToast(e.message,'error')}}
async function profileRenew(id){if(!state.certData.some(x=>Number(x.certification_id)===Number(id)))state.certData=await api('/api/certifications?limit=5000');closeEmployeeProfile();openCertificationRenew(id)}
function profileExport(){if(state.profile?.employee?.employee_pk)window.location.href=`/api/employees/${Number(state.profile.employee.employee_pk)}/export`}
async function runGlobalSearch(){const input=document.getElementById('global-search'),box=document.getElementById('global-search-results'),q=input.value.trim();if(q.length<2){box.classList.add('hidden');box.innerHTML='';return}try{const rows=await api('/api/search?q='+encodeURIComponent(q)+'&limit=15');box.innerHTML=rows.map(x=>`<button class="search-result" onclick='openSearchResult(${JSON.stringify(x.type)},${Number(x.entity_id||0)},${x.employee_pk===null?'null':Number(x.employee_pk)},${JSON.stringify(x.label)})'><span class="search-type">${esc(x.type)}</span><div><strong>${esc(x.label)}</strong><small>${esc(x.subtitle||'')}</small></div></button>`).join('')||'<div class="empty-search">No result.</div>';box.classList.remove('hidden')}catch(e){box.innerHTML=`<div class="empty-search">${esc(e.message)}</div>`;box.classList.remove('hidden')}}
function openSearchResult(type,id,employeePk,label){document.getElementById('global-search-results').classList.add('hidden');if(type==='Employee')openEmployeeProfile(id);else if(type==='Action'){goTo('actions');setTimeout(()=>openActionManage(id),250)}else if(type==='Certification'){goTo('certification');document.getElementById('cert-search').value=label;loadCertification()}else if(type==='Training'){goTo('training');document.getElementById('training-search').value=label;loadTraining()}}

function analyticsValue(v,suffix=''){return v===null||v===undefined||v===''?'<span class="analytics-na">Not Available</span>':`${esc(v)}${suffix}`}
function renderAnalyticsBars(id,rows,labelKey='status',valueKey='total'){
  const el=document.getElementById(id);if(!el)return;const arr=rows||[];if(!arr.length){el.innerHTML='<div class="empty-state"><strong>Belum ada data</strong><span>Data akan muncul setelah record operasional tersedia.</span></div>';return}
  const max=Math.max(...arr.map(x=>Number(x[valueKey]||0)),1);el.innerHTML=arr.map(x=>{const v=Number(x[valueKey]||0),w=Math.max(2,v/max*100);return `<div class="analytics-bar-row"><div class="analytics-bar-label"><span>${esc(x[labelKey]||'—')}</span><strong>${esc(v)}</strong></div><div class="analytics-bar-track"><div class="analytics-bar-fill" style="width:${w}%"></div></div></div>`}).join('')
}
function renderAnalyticsTrend(t){const el=document.getElementById('analytics-trend'),rows=t?.points||[];if(!rows.length){el.innerHTML='<div class="empty-state"><strong>Belum ada monthly snapshot</strong><span>Snapshot pertama akan dibuat otomatis dari current operational state.</span></div>';return}if(!t.history_ready){const r=rows[rows.length-1];el.innerHTML=`<div class="trend-single"><span>Current Snapshot</span><strong>${esc(r.period_key)}</strong><div>Potential Gap <b>${esc(r.potential_gap_count||0)}</b> · Validation <b>${esc(r.validation_required_count||0)}</b> · Expired Action <b>${esc(r.expired_requiring_action||0)}</b></div><small>Minimal dua bulan diperlukan untuk membaca trend.</small></div>`;return}const vals=rows.map(x=>Number(x.potential_gap_count||0)),max=Math.max(...vals,1);el.innerHTML=`<div class="trend-bars">${rows.map(x=>`<div class="trend-col"><span class="trend-value">${esc(x.potential_gap_count||0)}</span><div class="trend-stick" style="height:${Math.max(4,Number(x.potential_gap_count||0)/max*100)}%"></div><small>${esc(x.period_key)}</small></div>`).join('')}</div><div class="helper" style="margin-top:10px">Potential Gap monthly snapshot. Hover/detail report tetap menggunakan database history.</div>`}
async function ensureAnalyticsDepartments(){if(state.analyticsDepartments.length)return;try{state.analyticsDepartments=await api('/api/analytics/departments');const sel=document.getElementById('analytics-department'),current=sel.value;sel.innerHTML='<option value="">All Departments</option>'+state.analyticsDepartments.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');sel.value=current}catch{}}
async function loadAnalytics(){try{await ensureAnalyticsDepartments();const dep=document.getElementById('analytics-department')?.value||'';const d=await api('/api/analytics/management?department='+encodeURIComponent(dep));state.analytics=d;document.getElementById('analytics-generated').textContent=`Generated ${new Date(d.generated_at).toLocaleString('id-ID')} · ${d.department||'All'}`;
  const s=d.summary||{};const cards=[
    ['Active Employees',s.active_employees,'','Current workforce'],
    ['Training Completion',s.training_completion_rate,'%',s.training_completion_rate==null?'Training History belum cukup':`${s.training_completed_requirements||0} / ${s.training_eligible_requirements||0} applicable requirement`],
    ['Certification Validity',s.certification_validity_rate,'%',`${s.certification_valid_records||0} / ${s.certification_dated_records||0} dated certification`],
    ['Requirement Coverage',s.requirement_coverage_rate,'%',`${s.requirement_covered_records||0} / ${s.requirement_current_records||0} current assessment record`],
    ['Potential Gap Resolution',s.potential_gap_resolution_rate,'%',s.potential_gap_resolution_rate==null?'Belum ada historical Potential Gap base':`${s.potential_gap_resolved||0} / ${s.potential_gap_historical_base||0} historical Potential Gap`],
    ['Action Closure',s.action_closure_rate,'%',`${s.action_closed||0} / ${s.action_actionable||0} actionable record`],
    ['Expired Need Action',s.expired_requiring_action,'','Explicit/direct-match follow-up'],
    ['Expired Need Review',s.expired_needing_review,'','Needs applicability/renewal review'],
    ['Overdue Actions',s.overdue_actions,'','Past due and not terminal'],
    ['Data Quality Flags',s.data_quality_issues,'','Total issue flags; bukan unique employee']
  ];document.getElementById('analytics-kpis').innerHTML=cards.map(([l,v,u,n])=>`<div class="kpi analytics-kpi"><div class="label">${esc(l)}</div><div class="value">${analyticsValue(v,u)}</div><span>${esc(n||'')}</span></div>`).join('');
  const readiness=d.data_readiness||{};document.getElementById('analytics-readiness').innerHTML=Object.entries(readiness).map(([k,v])=>`<div class="readiness-card ${v.ready?'ready':'waiting'}"><span>${v.ready?'✓':'!'}</span><div><strong>${esc(k.replaceAll('_',' '))}</strong><small>${esc(v.note||'')}</small></div></div>`).join('');
  renderAnalyticsBars('analytics-coverage-bars',d.coverage?.status||[],'status','total');renderAnalyticsBars('analytics-cert-bars',d.certification?.expiry_by_month||[],'month','total');renderAnalyticsBars('analytics-action-bars',d.actions?.by_status||[],'status','total');renderAnalyticsBars('analytics-quality-bars',(d.data_quality?.issues||[]).filter(x=>Number(x.count)>0),'issue','count');renderAnalyticsTrend(d.trend);
  document.getElementById('analytics-gap-body').innerHTML=(d.coverage?.top_potential_gap_requirements||[]).map(x=>`<tr><td>${esc(x.training_name)}</td><td>${esc(x.employee_count)}</td><td>${tag(x.priority||'—')}</td></tr>`).join('')||'<tr><td colspan="3">Tidak ada current Potential Gap.</td></tr>';
  const up=d.upcoming_90_days||{},uc=up.counts||{};document.getElementById('analytics-upcoming-summary').innerHTML=`<span><strong>${esc(uc.certifications||0)}</strong> certification expiry</span><span><strong>${esc(uc.actions||0)}</strong> action due</span><span><strong>${esc(uc.scheduled_training||0)}</strong> scheduled training</span>`;document.getElementById('analytics-upcoming-body').innerHTML=(up.certifications||[]).slice(0,12).map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${esc(x.certification_name)}</td><td>${esc(x.expiry_date)}</td><td>${esc(x.days_remaining)}</td></tr>`).join('')||'<tr><td colspan="4">Tidak ada certification expiry dalam 90 hari.</td></tr>';
  document.getElementById('analytics-department-body').innerHTML=(d.department_comparison||[]).map(x=>`<tr><td><strong>${esc(x.department)}</strong></td><td>${esc(x.active_employees)}</td><td>${esc(x.assessment_records)}</td><td>${analyticsValue(x.requirement_coverage_rate,'%')}</td><td>${esc(x.potential_gap)}</td><td>${esc(x.validation_required)}</td><td>${esc(x.not_assessed)}</td><td>${esc(x.expired_certifications)}</td><td>${esc(x.open_actions)}</td><td>${esc(x.overdue_actions)}</td></tr>`).join('')||'<tr><td colspan="10">Department data belum tersedia.</td></tr>';
  document.getElementById('analytics-definitions').innerHTML=(d.definitions||[]).map(x=>`<div class="definition"><span>${esc(x.metric)}</span><p>${esc(x.definition)}</p></div>`).join('');
}catch(e){showToast(e.message,'error')}}
