async function loadDefinitions(key,id){if(!state.defs[key])state.defs=await api('/api/definitions');renderDefs(key,id)}
function renderDonut(el,data){if(!data?.length){el.innerHTML='<div class="empty-state"><strong>Belum ada data</strong></div>';return}const total=data.reduce((a,x)=>a+Number(x.total||0),0)||1;const colors=['#2563eb','#f59e0b','#22c55e','#ef4444','#8b5cf6','#14b8a6'];let cursor=0;const stops=[];data.forEach((x,i)=>{const start=cursor;cursor+=Number(x.total||0)/total*360;stops.push(`${colors[i%colors.length]} ${start}deg ${cursor}deg`)});const legend=data.map((x,i)=>`<div class="legend-item"><div class="legend-left"><span class="legend-dot" style="background:${colors[i%colors.length]}"></span>${esc(x.status||x.priority||'Unknown')}</div><strong>${esc(x.total)}</strong></div>`).join('');el.innerHTML=`<div class="donut" style="background:conic-gradient(${stops.join(',')})"><div class="donut-center"><strong>${total}</strong><span>records</span></div></div><div class="legend">${legend}</div>`}
async function loadDashboard(){try{
  const d=await api('/api/dashboard'),k=d.kpi||{};
  const cards=[
    ['Active Employees',k.employees,'employee','Current workforce'],['Active Requirements',k.active_requirements,'training','Position-based needs'],['Certifications',k.certifications,'certification','Current records'],['Training History',k.training_history,'history','Actual records'],
    ['Pending Assessment',(k.pending_initial||0)+(k.assessment_ready||0)+(k.pending_reassessment||0),'assessment','Initial + reassessment'],['High Priority',k.high_actions,'actions','Open action priority'],['Near Expiry ≤90d',k.near_expiry_90d,'certification','Renewal monitoring'],['Overdue Actions',k.overdue_actions,'actions','Past due date']
  ];
  document.getElementById('kpis').innerHTML=cards.map(([l,v,page,note])=>`<button class="kpi kpi-click" onclick="goTo('${page}')"><div class="label">${esc(l)}</div><div class="value">${esc(v??0)}</div><span>${esc(note)}</span></button>`).join('');
  document.getElementById('hero-employees').textContent=k.employees??0;document.getElementById('hero-certs').textContent=k.certifications??0;document.getElementById('hero-attention').textContent=k.open_actions??0;document.getElementById('dashboard-updated').textContent='Database live · '+new Date().toLocaleString('id-ID');
  renderDonut(document.getElementById('status-pie'),d.decision_status);renderDonut(document.getElementById('priority-pie'),d.priority);
  const needs=(d.needs_attention||[]).filter(x=>Number(x.count)>0);document.getElementById('needs-attention').innerHTML=needs.map(x=>`<button class="attention-item ${esc(x.severity)}" onclick='openAttention(${JSON.stringify(x.page)},${JSON.stringify(x.filter||'')})'><div><strong>${esc(x.label)}</strong><span>${attentionHint(x.key)}</span></div><b>${esc(x.count)}</b></button>`).join('')||'<div class="empty-state"><strong>No urgent item</strong><span>Tidak ada item aktif yang membutuhkan perhatian khusus.</span></div>';
  const prog=d.action_progress||[];const total=prog.reduce((a,x)=>a+Number(x.total||0),0)||1;document.getElementById('action-progress').innerHTML=prog.length?prog.map(x=>`<div class="progress-row"><div class="progress-label"><span>${esc(x.status)}</span><strong>${esc(x.total)}</strong></div><div class="progress-track"><div class="progress-fill" style="width:${Math.max(3,Number(x.total||0)/total*100)}%"></div></div></div>`).join(''):'<div class="empty-state"><strong>Belum ada action</strong><span>Recommendation dapat dibuat menjadi action dari Competency Explorer.</span></div>';
  document.getElementById('upcoming-cert-body').innerHTML=(d.upcoming_certifications||[]).map(x=>`<tr><td><button class="text-link" onclick="openEmployeeProfile(${Number(x.employee_pk)})">${esc(x.employee_name)}</button></td><td>${esc(x.certification_name)}</td><td>${esc(x.expiry_date)}</td><td class="${Number(x.days_remaining)<=30?'text-danger':''}">${esc(x.days_remaining)}</td><td>${tag(x.renewal_status||'Not Due')}</td></tr>`).join('')||'<tr><td colspan="5">Tidak ada sertifikasi jatuh tempo dalam 180 hari.</td></tr>';
  document.getElementById('recent-activity').innerHTML=(d.recent_activity||[]).map(x=>`<div class="activity-item"><div class="activity-dot"></div><div><strong>${esc(activityLabel(x.action,x.dataset_type))}</strong><span>${esc(x.details||x.target||'Database updated')}</span><small>${esc(x.created_at)} · ${esc(x.user_name||'System')}</small></div></div>`).join('')||'<div class="empty-state">Belum ada recent activity.</div>';
  document.getElementById('notification-badge').textContent=k.unread_notifications||0;await loadDefinitions('Dashboard','dashboard-definitions')
}catch(e){document.getElementById('kpis').innerHTML=`<div class="notice">Dashboard gagal dimuat: ${esc(e.message)}</div>`}}
function attentionHint(k){return {expired:'Review renewal / applicability',potential_high:'Validate evidence or create action',overdue:'Follow-up melewati due date',urgent_expiry:'Prepare renewal',validation:'Review mapping / evidence',pending_reassessment:'Evidence berubah; assessment perlu dihitung ulang',unassigned:'Action belum memiliki PIC'}[k]||'Open related workflow'}
function activityLabel(a,d){return String(a||'UPDATE').replaceAll('_',' ')+' · '+String(d||'System')}
function openAttention(page,filter){if(page==='certification'&&filter){state.certStatus=filter;document.querySelectorAll('[data-cert]').forEach(x=>x.classList.toggle('active',x.dataset.cert===filter))}if(page==='competency'&&filter){document.getElementById('competency-filter').value=filter}if(page==='actions'&&filter==='overdue'){document.getElementById('action-status-filter').value=''}goTo(page)}
async function loadRefs(force=false){if(force||!state.refs.positions.length){const [positions,training,certifications]=await Promise.all([api('/api/reference/positions'),api('/api/reference/training-catalog'),api('/api/reference/certification-catalog')]);state.refs={positions,training,certifications}}return state.refs}
async function loadEmployees(){try{state.employeeData=await api('/api/employees?limit=5000&include_inactive=true');renderEmployees(state.employeeData)}catch(e){document.getElementById('employee-body').innerHTML=`<tr><td colspan="7">${esc(e.message)}</td></tr>`}}
function isPurgeEligibleEmployee(x){return /^(UAT-|TEST-|DUMMY-)/i.test(String(x?.employee_code||'').trim())}
function lifecycleActions(x){const view=`<button class="mini-btn profile-btn" onclick="openEmployeeProfile(${x.employee_pk})">View Profile</button>`;const purge=state.auth?.user?.role==='supervisor_tcd'&&isPurgeEligibleEmployee(x)?`<button class="mini-btn danger" onclick="openEmployeePurge(${x.employee_pk})">Delete Test Data</button>`:'';if(!Number(x.active_flag))return `${view}${purge}`;const st=String(x.assessment_state||'Assessed');const base=can('employee_manage')?`<button class="mini-btn" onclick="openEmployeeEdit(${x.employee_pk})">Edit</button><button class="mini-btn" onclick="openPositionChange(${x.employee_pk})">Change Position</button>`:'';let life='';if(can('assessment_manage')){if(st==='Pending Initial Assessment')life=`<button class="mini-btn primary-mini" onclick="openConfirmInitialData(${x.employee_pk})">Confirm Data</button>`;else if(st==='Assessment Ready')life=`<button class="mini-btn primary-mini" onclick="runInitialAssessment(${x.employee_pk})">Run Assessment</button>`;else if(st==='Pending Reassessment')life=`<button class="mini-btn primary-mini" onclick="runReassessment(${x.employee_pk})">Reassess</button>`}return `${view}${life}${base}${can('employee_manage')?`<button class="mini-btn danger" onclick="openEmployeeDeactivate(${x.employee_pk})">Deactivate</button>`:''}${purge}`}
function renderEmployees(rows){const q=(document.getElementById('employee-search')?.value||'').toLowerCase();const f=rows.filter(x=>[x.employee_code,x.employee_name,x.position_name,x.department,x.employment_status,x.assessment_state].some(v=>String(v||'').toLowerCase().includes(q)));document.getElementById('employee-body').innerHTML=f.map(x=>{const attention=[];if(Number(x.potential_gap_count))attention.push(`<span class="attention-mini high">${x.potential_gap_count} Potential Gap</span>`);if(Number(x.validation_count))attention.push(`<span class="attention-mini attention">${x.validation_count} Validation</span>`);if(Number(x.open_action_count))attention.push(`<span class="attention-mini info">${x.open_action_count} Open Action</span>`);return `<tr class="${Number(x.active_flag)?'':'row-muted'}"><td>${esc(x.employee_code||'—')}</td><td><button class="employee-link" onclick="openEmployeeProfile(${x.employee_pk})">${esc(x.employee_name)}</button><span class="sub">${esc(x.employment_status||'—')} · ${esc(x.certification_count||0)} certification</span></td><td>${esc(x.position_name||'—')}</td><td>${esc(x.department||'—')}</td><td>${tag(x.assessment_state||'—')}<span class="sub">${esc(x.requirement_count||0)} applicable requirement</span></td><td><div class="attention-mini-wrap">${attention.join('')||'<span class="sub">No active attention</span>'}</div></td><td><div class="row-actions lifecycle-actions">${lifecycleActions(x)}</div></td></tr>`}).join('')||'<tr><td colspan="7">Tidak ada employee.</td></tr>'}
async function openConfirmInitialData(id){try{const r=await api(`/api/employees/${id}/assessment-readiness`);const note=`Employee: ${r.employee_name} | Position: ${r.position_name||'—'} | Applicable Requirements: ${r.applicable_requirements} | Training History: ${r.training_history_records} | Certifications: ${r.certification_records}. Konfirmasi berarti data awal yang tersedia sudah selesai diperiksa. Nilai evidence boleh 0 jika memang belum ada.`;openCrud('Confirm Initial Assessment Data',[{name:'remarks',label:'Confirmation Note',type:'textarea',value:'Initial available data reviewed by TCD.'}],async o=>jsonApi(`/api/employees/${id}/assessment/confirm-initial-data`,'POST',o),{note,submit:'Confirm Initial Data'})}catch(e){showToast(e.message,'error')}}
async function runInitialAssessment(id){const x=state.employeeData.find(r=>Number(r.employee_pk)===Number(id));if(!confirm(`Run Initial Assessment untuk ${x?.employee_name||'employee'}? Decision Engine akan membuat assessment berdasarkan requirement dan evidence yang sudah dikonfirmasi.`))return;try{const d=await jsonApi(`/api/employees/${id}/assessment/run`,'POST',{});const z=d.distribution||{};showToast(`Initial Assessment selesai: ${d.applicable_requirements} requirement | Covered ${z.Covered||0} | Potential Gap ${z['Potential Gap']||0} | Validation ${z['Validation Required']||0} | Not Assessed ${z['Not Assessed']||0}`);await Promise.allSettled([loadEmployees(),loadDashboard(),loadCompetency(),loadAssessmentQueue()])}catch(e){showToast(e.message,'error')}}
async function runReassessment(id){const x=state.employeeData.find(r=>Number(r.employee_pk)===Number(id));if(!confirm(`Reassess ${x?.employee_name||'employee'}? Current assessment akan dihitung ulang dari evidence terbaru dan hasil baru disimpan ke assessment history.`))return;try{const d=await jsonApi(`/api/employees/${id}/assessment/reassess`,'POST',{});const z=d.distribution||{};showToast(`Reassessment selesai: ${d.applicable_requirements} requirement | Covered ${z.Covered||0} | Potential Gap ${z['Potential Gap']||0} | Validation ${z['Validation Required']||0} | Not Assessed ${z['Not Assessed']||0}`);await Promise.allSettled([loadEmployees(),loadDashboard(),loadCompetency(),loadAssessmentQueue()])}catch(e){showToast(e.message,'error')}}
function renderAssessmentQueue(){const q=(document.getElementById('assessment-search')?.value||'').toLowerCase();const sf=document.getElementById('assessment-state-filter')?.value||'';const rows=(state.assessmentData||[]).filter(x=>(!sf||String(x.assessment_state)===sf)&&(!q||[x.employee_name,x.employee_code,x.position_name,x.assessment_state].some(v=>String(v||'').toLowerCase().includes(q))));document.getElementById('assessment-body').innerHTML=rows.map(x=>`<tr><td><strong>${esc(x.employee_name)}</strong><span class="sub">${esc(x.employee_code||'')}</span></td><td>${esc(x.position_name||'—')}</td><td>${tag(x.assessment_state)}</td><td>${esc(x.applicable_requirements)}</td><td>${esc(x.training_history_records)}</td><td>${esc(x.certification_records)}</td><td>${esc(x.last_assessment_at||'—')}</td><td><div class="row-actions">${can('assessment_manage')?(x.assessment_state==='Pending Initial Assessment'?`<button class="mini-btn primary-mini" onclick="openConfirmInitialData(${x.employee_pk})">Confirm Data</button>`:x.assessment_state==='Assessment Ready'?`<button class="mini-btn primary-mini" onclick="runInitialAssessment(${x.employee_pk})">Run Assessment</button>`:x.assessment_state==='Pending Reassessment'?`<button class="mini-btn primary-mini" onclick="runReassessment(${x.employee_pk})">Reassess</button>`:''):'<span class="sub">Supervisor TCD action</span>'}</div></td></tr>`).join('')||'<tr><td colspan="8">Tidak ada employee yang sesuai filter.</td></tr>'}
async function loadAssessmentQueue(){try{const d=await api('/api/assessment-queue?limit=5000');state.assessmentData=d.records||[];const sm=Object.fromEntries((d.summary||[]).map(x=>[x.state,Number(x.total||0)]));document.getElementById('assessment-state-cards').innerHTML=[['Pending Initial Assessment',sm['Pending Initial Assessment']||0],['Assessment Ready',sm['Assessment Ready']||0],['Pending Reassessment',sm['Pending Reassessment']||0],['Assessed',sm['Assessed']||0]].map(([l,v])=>`<div class="kpi"><div class="label">${esc(l)}</div><div class="value">${esc(v)}</div></div>`).join('');renderAssessmentQueue();await loadDefinitions('Assessment Queue','assessment-definitions')}catch(e){document.getElementById('assessment-body').innerHTML=`<tr><td colspan="8">${esc(e.message)}</td></tr>`}}


async function loadTraining(){try{state.trainingData=await api('/api/training-requirements?limit=5000');const allEmployees=await api('/api/employees?limit=5000');state.trainingEmployees=allEmployees;populateTrainingFilters(state.trainingData,allEmployees);renderTraining(state.trainingData);await loadDefinitions('Training','training-definitions')}catch(e){document.getElementById('training-body').innerHTML=`<tr><td colspan="8">${esc(e.message)}</td></tr>`}}
function shortenNames(v){const names=String(v||'').split(',').map(x=>x.trim()).filter(Boolean);if(!names.length)return 'Belum ada karyawan terpetakan';return names.length<=5?names.join(', '):`${names.slice(0,5).join(', ')} (+${names.length-5} lainnya)`}
function populateTrainingFilters(rows,employees=[]){
  const setOptions=(id,vals,label)=>{const el=document.getElementById(id);if(!el)return;const current=el.value;const uniq=[...new Set(vals.map(v=>String(v||'').trim()).filter(v=>v))].sort((a,b)=>a.localeCompare(b));el.innerHTML=`<option value="">${label}</option>`+uniq.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');el.value=uniq.includes(current)?current:''};
  const empEl=document.getElementById('training-employee-filter');
  if(empEl){const current=empEl.value;const ordered=[...employees].filter(x=>Number(x.active_flag)!==0).sort((a,b)=>String(a.employee_name||'').localeCompare(String(b.employee_name||'')));empEl.innerHTML='<option value="">Semua Karyawan</option>'+ordered.map(x=>`<option value="${Number(x.employee_pk)}">${esc(x.employee_name)}${x.employee_code?` — ${esc(x.employee_code)}`:''}</option>`).join('');empEl.value=ordered.some(x=>String(x.employee_pk)===String(current))?current:'';}
  setOptions('training-position-filter',rows.map(x=>x.position_name),'Semua Jabatan');
  setOptions('training-department-filter',[...rows.map(x=>x.department),...employees.map(x=>x.department)],'Semua Departemen');
}
function trainingEmployeeMatchesQuery(q){
  const needle=String(q||'').trim().toLowerCase();
  if(!needle)return [];
  return (state.trainingEmployees||[]).filter(e=>Number(e.active_flag)!==0&&[e.employee_name,e.employee_code].some(v=>String(v||'').toLowerCase().includes(needle)));
}
function trainingEffectiveEmployeePk(){
  const explicit=document.getElementById('training-employee-filter')?.value||'';
  if(explicit)return explicit;
  const q=document.getElementById('training-search')?.value||'';
  const matches=trainingEmployeeMatchesQuery(q);
  return matches.length===1?String(matches[0].employee_pk):'';
}
function renderTraining(rows){
  const q=(document.getElementById('training-search').value||'').trim().toLowerCase();
  const employeePk=document.getElementById('training-employee-filter').value||'';
  const explicitEmployee=employeePk?(state.trainingEmployees||[]).find(e=>String(e.employee_pk)===String(employeePk)):null;
  const searchEmployees=!explicitEmployee&&q?trainingEmployeeMatchesQuery(q):[];
  const employeeContexts=explicitEmployee?[explicitEmployee]:searchEmployees;
  const employeeContextMode=employeeContexts.length>0;
  const pf=(document.getElementById('training-position-filter').value||'').toLowerCase();
  const df=(document.getElementById('training-department-filter').value||'').toLowerCase();
  const tf=(document.getElementById('training-type-filter').value||'').toLowerCase();
  const projected=[];
  rows.forEach(x=>{
    const pos=String(x.position_name||'').toLowerCase(),dep=String(x.department||'').toLowerCase(),tr=String(x.training_name||'').toLowerCase(),typ=String(x.requirement_type||'').toLowerCase();
    if((pf&&pos!==pf)||(df&&dep!==df)||(tf&&typ!==tf))return;
    if(employeeContextMode){
      employeeContexts.forEach(emp=>{
        if(Number(x.position_id)!==Number(emp.current_position_id))return;
        const empText=`${String(emp.employee_name||'')} ${String(emp.employee_code||'')}`.toLowerCase();
        const searchMatch=!q||explicitEmployee?[empText,pos,dep,tr].some(v=>v.includes(q)):true;
        if(searchMatch)projected.push({row:x,employee:emp});
      });
    }else{
      const displayEmp=String(x.employee_names||'').toLowerCase();
      if(!q||[displayEmp,pos,dep,tr].some(v=>v.includes(q)))projected.push({row:x,employee:null});
    }
  });
  const header=document.getElementById('training-employee-header');
  if(header)header.textContent=employeeContextMode?'Employee':'Employee(s)';
  document.getElementById('training-body').innerHTML=projected.slice(0,1200).map(item=>{const x=item.row,emp=item.employee;const empName=emp?emp.employee_name:shortenNames(x.employee_names);const empSub=emp?(emp.employee_code||'Employee context'):`${x.employee_count||0} karyawan`;return `<tr class="${String(x.requirement_status||'Active')==='Active'?'':'row-muted'}"><td><strong>${esc(empName)}</strong><span class="sub">${esc(empSub)}</span></td><td>${esc(x.position_name)}</td><td>${esc(emp?.department||x.department||'—')}</td><td><strong>${esc(x.training_name)}</strong></td><td>${tag(x.requirement_type)}</td><td>${esc(x.delivery_type||'—')}</td><td>${esc(x.regulatory_flag||'—')}</td><td><div class="row-actions">${can('requirement_manage')?`<button class="mini-btn" onclick="openRequirementEdit(${x.requirement_id})">Edit</button>${String(x.requirement_status||'Active')==='Active'?`<button class="mini-btn danger" onclick="openRequirementDeactivate(${x.requirement_id})">Deactivate</button>`:''}`:'<span class="sub">View only</span>'}</div></td></tr>`}).join('')||`<tr><td colspan="8">Tidak ada data yang sesuai.</td></tr>`;
}
async function loadHistory(){try{state.historyData=await api('/api/training-history?limit=5000');renderHistory(state.historyData);await loadDefinitions('Training History','history-definitions')}catch(e){document.getElementById('history-body').innerHTML=`<tr><td colspan="8">${esc(e.message)}</td></tr>`}}
function renderHistory(rows){const q=(document.getElementById('history-search').value||'').toLowerCase();const f=rows.filter(x=>[x.employee_name,x.position_name,x.training_name].some(v=>String(v||'').toLowerCase().includes(q)));const empty=document.getElementById('history-empty');empty.style.display=f.length?'none':'block';document.getElementById('history-body').innerHTML=f.slice(0,1000).map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${esc(x.position_name||'—')}</td><td>${esc(x.training_name)}</td><td>${esc(x.completion_date||'—')}</td><td>${tag(x.completion_status||'—')}</td><td>${esc(x.provider||'—')}</td><td>${esc(x.evidence_note||x.certificate_reference||'—')}</td><td><div class="row-actions"><button class="mini-btn" onclick="openHistoryEdit(${x.history_id})">Edit</button><button class="mini-btn danger" onclick="archiveHistory(${x.history_id})">Archive</button></div></td></tr>`).join('')}
async function loadCertification(){try{const p=new URLSearchParams({limit:'5000'});if(state.certStatus)p.set('status',state.certStatus);const q=document.getElementById('cert-search').value.trim();if(q)p.set('search',q);state.certData=await api('/api/certifications?'+p.toString());renderCertification(state.certData);await loadDefinitions('Certification','cert-definitions')}catch(e){document.getElementById('cert-body').innerHTML=`<tr><td colspan="7">${esc(e.message)}</td></tr>`}}
function renderCertification(rows){document.getElementById('cert-body').innerHTML=rows.slice(0,1500).map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${esc(x.position_name||'—')}</td><td><strong>${esc(x.certification_name)}</strong><span class="sub">${esc(x.certificate_number||'')}</span></td><td>${tag(x.display_status)}</td><td>${esc(x.expiry_date||'—')}</td><td>${tag(x.renewal_status||'—')}</td><td><div class="row-actions"><button class="mini-btn" onclick="openCertificationEdit(${x.certification_id})">Edit</button><button class="mini-btn primary-mini" onclick="openCertificationRenew(${x.certification_id})">Renew</button><button class="mini-btn" onclick="openCertificationNotRenewed(${x.certification_id})">Not Renewed</button></div></td></tr>`).join('')||`<tr><td colspan="7">Tidak ada data yang sesuai.</td></tr>`}
async function loadCompetency(){try{const p=new URLSearchParams({limit:'5000'});const s=document.getElementById('competency-filter').value;const q=document.getElementById('comp-search').value.trim();if(s)p.set('status',s);if(q)p.set('search',q);state.compData=await api('/api/competency?'+p.toString());renderCompetency(state.compData);await loadDefinitions('Competency','comp-definitions')}catch(e){document.getElementById('competency-body').innerHTML=`<tr><td colspan="8">${esc(e.message)}</td></tr>`}}
function renderCompetency(rows){document.getElementById('competency-body').innerHTML=rows.slice(0,1500).map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${esc(x.position_name||'—')}</td><td>${esc(x.training_name)}</td><td>${tag(x.final_status)}</td><td>${tag(x.priority)}</td><td>${tag(x.assessment_source||'Legacy')}</td><td>${esc(x.evidence_confidence||'—')}</td><td><div class="row-actions"><span class="sub">${esc(x.decision_action||'—')}</span>${can('action_manage')&&x.employee_pk&&x.requirement_id?`<button class="mini-btn" onclick="openActionFromCompetency(${Number(x.employee_pk)},${Number(x.requirement_id)})">Create Action</button>`:''}</div></td></tr>`).join('')||`<tr><td colspan="8">Tidak ada data yang sesuai.</td></tr>`}
function populateValidationFilters(){const set=(id,values,label)=>{const el=document.getElementById(id);if(!el)return;const cur=el.value;const vals=[...new Set(values.map(v=>String(v||'').trim()).filter(Boolean))].sort();el.innerHTML=`<option value="">${label}</option>`+vals.map(v=>`<option>${esc(v)}</option>`).join('');el.value=vals.includes(cur)?cur:''};set('validation-mapping-filter',(state.validationData||[]).map(x=>x.mapping_category),'All Mapping');set('validation-priority-filter',(state.validationData||[]).map(x=>x.priority),'All Priority')}
function renderValidation(){const q=(document.getElementById('validation-search')?.value||'').toLowerCase(),mf=document.getElementById('validation-mapping-filter')?.value||'',pf=document.getElementById('validation-priority-filter')?.value||'';const rows=(state.validationData||[]).filter(x=>(!mf||String(x.mapping_category)===mf)&&(!pf||String(x.priority)===pf)&&(!q||[x.employee_name,x.position_name,x.training_name,x.certification_candidate].some(v=>String(v||'').toLowerCase().includes(q))));document.getElementById('validation-body').innerHTML=rows.map(x=>`<tr><td>${esc(x.employee_name)}</td><td>${esc(x.position_name||'—')}</td><td>${esc(x.training_name)}</td><td>${tag(x.mapping_category||'—')}</td><td>${esc(x.certification_candidate||'—')}</td><td>${tag(x.priority)}</td><td>${can('validation_manage')?`<button class="mini-btn primary-mini" onclick="openValidationReview(${Number(x.employee_pk)},${Number(x.requirement_id)})">Review</button>`:'<span class="sub">View only</span>'}</td></tr>`).join('')||`<tr><td colspan="7">Tidak ada item validation yang sesuai filter.</td></tr>`}
async function loadValidation(){try{state.validationData=await api('/api/validation-queue?limit=2000');populateValidationFilters();renderValidation()}catch(e){document.getElementById('validation-body').innerHTML=`<tr><td colspan="7">${esc(e.message)}</td></tr>`}}

async function loadData(){try{const [rows,batches]=await Promise.all([api('/api/data-management/logs?limit=100'),api('/api/data-management/import/batches?limit=50')]);document.getElementById('log-body').innerHTML=rows.map(x=>`<tr><td>${esc(x.source_file)}</td><td>${esc(x.dataset_type)}</td><td>${esc(x.rows_read)}</td><td>${esc(x.rows_imported)}</td><td>${esc(x.rows_rejected)}</td><td>${tag(x.status)}</td><td>${esc(x.imported_at)}</td></tr>`).join('')||`<tr><td colspan="7">Belum ada import log.</td></tr>`;document.getElementById('batch-body').innerHTML=batches.map(x=>`<tr><td><strong>${esc(x.batch_id)}</strong><span class="sub">${esc(x.source_file)}</span></td><td>${esc(x.dataset_type)}</td><td>${tag(x.status)}</td><td>${esc(x.rows_read)}</td><td>${esc(x.rows_imported)}</td><td>${esc(x.created_at)}</td></tr>`).join('')||'<tr><td colspan="6">Belum ada import batch.</td></tr>';await loadDefinitions('Data Management','data-definitions')}catch(e){document.getElementById('log-body').innerHTML=`<tr><td colspan="7">${esc(e.message)}</td></tr>`}}
function openTrainingDetail(id){
  const items=trainingDetailMap.get(id)||[];
  let modal=document.getElementById('training-detail-modal');
  if(!modal){
    modal=document.createElement('div'); modal.id='training-detail-modal'; modal.className='detail-modal-backdrop';
    modal.innerHTML=`<div class='detail-modal' role='dialog' aria-modal='true' aria-labelledby='training-detail-title'><div class='detail-modal-head'><div><div class='detail-kicker'>Training Requirement</div><h3 id='training-detail-title'>Detail Training</h3></div><button class='detail-close' type='button' aria-label='Tutup'>×</button></div><div id='training-detail-body' class='detail-modal-body'></div></div>`;
    document.body.appendChild(modal);
    modal.addEventListener('click',e=>{if(e.target===modal) modal.classList.remove('open')});
    modal.querySelector('.detail-close').addEventListener('click',()=>modal.classList.remove('open'));
  }
  const body=modal.querySelector('#training-detail-body');
  body.innerHTML=items.length?`<div class='detail-count'>${items.length} training requirement</div><ol>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:`<div class='empty-state'>Tidak ada training requirement.</div>`;
  modal.querySelector('#training-detail-title').textContent=`Detail Training (${items.length})`;
  modal.classList.add('open');
}
function detailList(items, empty='Tidak ada detail.'){
  const arr=Array.isArray(items)?items:[];
  return arr.length ? `<ol>${arr.map(x=>`<li>${esc(typeof x==='string'?x:(x.label||x.item||x.status||JSON.stringify(x)))}</li>`).join('')}</ol>` : `<div class='empty-state'>${esc(empty)}</div>`;
}
function conditionsDetail(r){
  const groups=Array.isArray(r.condition_details)?r.condition_details:[];
  const trainingCount=Number(r.training_count||0);
  const certs=Array.isArray(r.certification_details)?r.certification_details:[];
  let html='';
  if(groups.length){html += groups.map(g=>`<div class='detail-group'><div class='detail-group-title'>${esc(g.domain||'Condition')}</div>${detailList(g.items||[])}</div>`).join('');}
  if(!html && r.conditions && r.conditions!=='—') html=`<p class='detail-text'>${esc(r.conditions)}</p>`;
  if(certs.length){html += `<div class='detail-group'><div class='detail-group-title'>Certification Detail</div><div class='mini-detail-table'><table><thead><tr><th>Certification</th><th>Status</th><th>Expiry Date</th></tr></thead><tbody>${certs.map(c=>`<tr><td>${esc(c.certification_name)}</td><td>${tag(c.status)}</td><td>${esc(c.expired_date||'—')}</td></tr>`).join('')}</tbody></table></div></div>`;}
  if(trainingCount){html += `<div class='detail-group'><div class='detail-group-title'>Training Requirement</div><p class='detail-text'>${trainingCount} requirement terkait karyawan/posisi.</p></div>`;}
  return html||`<div class='empty-state'>Tidak ada kondisi tambahan.</div>`;
}
function certificationDetail(r){
  const certs=Array.isArray(r.certification_details)?r.certification_details:[];
  return certs.length ? `<div class='mini-detail-table'><table><thead><tr><th>Certification</th><th>Status</th><th>Certification Date</th><th>Expiry Date</th></tr></thead><tbody>${certs.map(c=>`<tr><td>${esc(c.certification_name)}</td><td>${tag(c.status)}</td><td>${esc(c.certification_date||'—')}</td><td>${esc(c.expired_date||'—')}</td></tr>`).join('')}</tbody></table></div>` : `<div class='empty-state'>Tidak ada record certification yang terkoordinasi.</div>`;
}
function clickableBox(label, sub, body, cls='detail-cell'){
  return `<details class='inline-detail ${cls}'><summary><strong>${esc(label)}</strong><span>${esc(sub||'Lihat detail →')}</span></summary><div class='inline-detail-panel'>${body}</div></details>`;
}
function domainRecords(d,agent){return Array.isArray(d?.results?.[agent]?.records)?d.results[agent].records:[]}
function aiDomainTable(title,helper,headers,rows){return `<div class='decision-box'><div class='decision-title'>${esc(title)}</div><div class='helper'>${esc(helper)}</div><div class='table-wrap' style='margin-top:10px;max-height:460px'><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan='${headers.length}'>Tidak ada record yang sesuai.</td></tr>`}</tbody></table></div></div>`}
function makeSingleDomainSummary(d){
  const intents=Array.isArray(d.intents)?d.intents:[]; if(intents.length!==1)return '';
  const intent=intents[0],details=new Set(Array.isArray(d.intent_details)?d.intent_details:[]);
  if(intent==='competency'){
    const data=domainRecords(d,'Competency Agent');
    const rows=data.map(r=>`<tr><td><strong>${esc(r.employee_name||'—')}</strong></td><td>${esc(r.position_tna||r.position_cert_db||'—')}</td><td>${esc(r.training_name||'—')}</td><td>${tag(r.coverage_status||r.final_status||'—')}</td><td>${tag(r.priority||'—')}</td><td>${esc(r.mapping_category||'—')}</td><td>${esc(r.certification_candidate||'—')}</td><td>${esc(r.recommendation||'—')}</td></tr>`).join('');
    return aiDomainTable(`Competency Evidence — ${data.length} record`,`Requirement coverage ditampilkan langsung; Potential Gap tetap merupakan indikasi yang perlu divalidasi, bukan competency gap final.`,['Employee','Position','Requirement','Coverage','Priority','Mapping','Certification Candidate','Recommended Action'],rows);
  }
  if(intent==='certification'){
    const data=domainRecords(d,'Certification Agent');
    const rows=data.map(r=>`<tr><td><strong>${esc(r.employee_name||'—')}</strong></td><td>${esc(r.position_name||'—')}</td><td>${esc(r.certification_name||'—')}</td><td>${tag(r.display_status||r.status||'—')}</td><td>${esc(r.certification_date||'—')}</td><td>${esc(r.expired_date||'—')}</td><td>${tag(r.renewal_status||'—')}</td></tr>`).join('');
    return aiDomainTable(`Certification Evidence — ${data.length} record`,`Status dan masa berlaku berasal dari record Certification.`,['Employee','Position','Certification','Status','Issue Date','Expiry Date','Renewal'],rows);
  }
  if(intent==='training'){
    const data=domainRecords(d,'Training Agent');
    if(details.has('training_history')||d.results?.['Training Agent']?.mode==='Training History'){
      const rows=data.map(r=>`<tr><td><strong>${esc(r.employee_name||'—')}</strong><span class="sub">${esc(r.employee_code||'—')}</span></td><td>${esc(r.position_name||'—')}</td><td>${esc(r.training_name||'—')}</td><td>${esc(r.training_date||r.completion_date||'—')}</td><td>${tag(r.history_result||'—')}</td><td>${esc(r.provider||'—')}</td><td>${esc(r.valid_until||'—')}</td></tr>`).join('');
      return aiDomainTable(`Training History — ${data.length} record`,`Hanya riwayat training aktual yang tercatat; hasil kosong tidak diganti dengan Training Requirement.`,['Employee','Position','Training','Date','Result','Provider','Valid Until'],rows);
    }
    if(details.has('training_fulfillment')){
      const rows=data.map(r=>`<tr><td><strong>${esc(r.employee_name||'—')}</strong></td><td>${esc(r.position_name||'—')}</td><td>${esc(r.training_name||'—')}</td><td>${tag(r.requirement_type||'—')}</td><td>${tag(r.fulfillment_status||'—')}</td><td>${esc(r.latest_completion_date||'—')}</td><td>${esc(r.history_result||'—')}</td><td>${esc(r.decision_action||'—')}</td></tr>`).join('');
      return aiDomainTable(`Training Fulfillment — ${data.length} requirement`,`Fulfillment membandingkan requirement dengan actual Training History; requirement saja tidak dianggap bukti completion.`,['Employee','Position','Training Requirement','Type','Fulfillment','Latest Completion','History Result','Follow-up'],rows);
    }
    const hasEmployee=data.some(r=>r.employee_name);
    const rows=data.map(r=>`<tr>${hasEmployee?`<td><strong>${esc(r.employee_name||'—')}</strong></td>`:''}<td>${esc(r.position_name||r.position_standard||r.position_raw||'—')}</td><td>${esc(r.training_name||'—')}</td><td>${tag(r.requirement_type||'—')}</td><td>${esc(r.delivery_type||'—')}</td><td>${esc(r.regulatory_flag||'—')}</td></tr>`).join('');
    return aiDomainTable(`Training Requirement — ${data.length} record`,`Training Requirement berasal dari kebutuhan posisi; pemenuhan aktual memerlukan Training History.`,[...(hasEmployee?['Employee']:[]),'Position','Training','Type','Delivery','Regulatory'],rows);
  }
  if(intent==='action'){
    const data=domainRecords(d,'Action Agent');
    const rows=data.map(r=>`<tr><td><strong>${esc(r.employee_name||'—')}</strong></td><td>${esc(r.title||r.training_name||'—')}</td><td>${esc(r.action_type||'—')}</td><td>${tag(r.priority||'—')}</td><td>${esc(r.pic_name||'Unassigned')}</td><td>${esc(r.due_date||'—')}</td><td>${tag(r.status||'—')}</td><td>${tag(r.closure_readiness||'—')}</td></tr>`).join('');
    return aiDomainTable(`Action Center — ${data.length} record`,`Informasi Action Center ditampilkan secara read-only. Perubahan tetap dilakukan dari menu Action Center.`,['Employee','Action','Type','Priority','PIC','Due','Status','Closure'],rows);
  }
  return '';
}
function makeDecisionSummary(d){
  const rows=d.decision_summary||[]; if(!rows.length)return '';
  const html=rows.map(r=>{
    const list=Array.isArray(r.training_requirement_list)?r.training_requirement_list:[];
    const training=list.length?clickableBox(`${list.length} training requirements`,'Lihat detail →',`<div class='detail-count'>${list.length} training requirement</div>${detailList(list)}`,'training-detail-cell'):`<span>—</span>`;
    const certCount=Number(r.certification_count||0);
    const cert=certCount?clickableBox(`${certCount} certification${certCount>1?'s':''}`,'Lihat detail →',certificationDetail(r),'cert-detail-cell'):`<span>—</span>`;
    const competency=r.coverage_status&&r.coverage_status!=='—'?`<strong>${esc(r.coverage_status)}</strong>`:`<span>—</span>`;
    return `<tr><td><strong>${esc(r.employee_name||'—')}</strong></td><td>${esc(r.position_name||'—')}</td><td>${competency}</td><td>${training}</td><td>${cert}</td><td>${tag(r.final_status)}</td><td>${tag(r.priority)}</td><td>${esc(r.recommended_action||'—')}</td></tr>`;
  }).join('');
  return `<div class='decision-box'><div class='decision-title'>Ringkasan Gabungan — ${esc(rows.length)} karyawan unik</div><div class='helper'>Ringkasan data lintas domain sesuai pertanyaan.</div><div class='table-wrap' style='margin-top:10px;max-height:460px'><table><thead><tr><th>Employee</th><th>Position</th><th>Competency</th><th>Training</th><th>Certification</th><th>Result</th><th>Priority</th><th>Recommended Action</th></tr></thead><tbody>${html}</tbody></table></div></div>`;
}

function showToast(msg,kind='ok'){const t=document.getElementById('toast');t.textContent=msg;t.className=`toast show ${kind}`;clearTimeout(t._timer);t._timer=setTimeout(()=>t.className='toast',3400)}
function optionsHtml(items,valueKey,labelFn,current=''){return `<option value="">-- pilih --</option>`+items.map(x=>`<option value="${esc(x[valueKey])}" ${String(x[valueKey])===String(current)?'selected':''}>${esc(labelFn(x))}</option>`).join('')}
function fieldHtml(f){const required=f.required?'required':'';const val=f.value??'';const fieldName=esc(f.name||'');const cls=`crud-field ${f.wide?'wide':''}`;if(f.type==='html')return `<div class="${cls}" data-field="${fieldName}"><span>${esc(f.label)}</span>${f.html||''}</div>`;if(f.type==='display')return `<label class="${cls}" data-field="${fieldName}"><span>${esc(f.label)}</span><div class="crud-display">${esc(val||'—')}</div></label>`;if(f.type==='select')return `<label class="${cls}" data-field="${fieldName}"><span>${esc(f.label)}${f.required?' *':''}</span><select name="${fieldName}" ${required}>${f.options||''}</select></label>`;if(f.type==='textarea')return `<label class="crud-field wide" data-field="${fieldName}"><span>${esc(f.label)}${f.required?' *':''}</span><textarea name="${fieldName}" rows="3" ${required}>${esc(val)}</textarea></label>`;return `<label class="${cls}" data-field="${fieldName}"><span>${esc(f.label)}${f.required?' *':''}</span><input name="${fieldName}" type="${esc(f.type||'text')}" value="${esc(val)}" ${required} ${f.placeholder?`placeholder="${esc(f.placeholder)}"`:''}/></label>`}
function openCrud(title,fields,onSubmit,{note='',submit='Save',hideSubmit=false,extraActions=[]}={}){const modal=document.getElementById('crud-modal');document.getElementById('crud-title').textContent=title;document.getElementById('crud-fields').innerHTML=fields.map(fieldHtml).join('');const n=document.getElementById('crud-note');n.textContent=note;n.classList.toggle('hidden',!note);const submitBtn=document.getElementById('crud-submit');submitBtn.textContent=submit;submitBtn.classList.toggle('hidden',!!hideSubmit);const form=document.getElementById('crud-form');const actions=form.querySelector('.crud-actions');actions.querySelectorAll('.crud-extra-action').forEach(x=>x.remove());for(const a of extraActions){const b=document.createElement('button');b.type='button';b.className=`${a.className||'chip'} crud-extra-action`;b.textContent=a.label||'Action';b.disabled=!!a.disabled;b.title=a.title||'';if(a.disabled)b.setAttribute('aria-disabled','true');b.onclick=async()=>{b.disabled=true;try{const obj=Object.fromEntries(new FormData(form).entries());await a.onClick(obj,b)}catch(err){showToast(err.message,'error')}finally{b.disabled=!!a.disabled}};actions.insertBefore(b,submitBtn)}form.onsubmit=async e=>{e.preventDefault();if(hideSubmit)return;const btn=submitBtn;btn.disabled=true;const obj=Object.fromEntries(new FormData(form).entries());try{await onSubmit(obj);closeCrud();showToast('Data berhasil diperbarui.');await refreshVisibleData();const profileEl=document.getElementById('employee-profile');const profileId=Number(state.profile?.employee?.employee_pk||0);if(profileId&&profileEl?.classList.contains('open'))await openEmployeeProfile(profileId,state.profileTab||'overview')}catch(err){showToast(err.message,'error')}finally{btn.disabled=false}};modal.classList.add('open');modal.setAttribute('aria-hidden','false')}
function closeCrud(){const modal=document.getElementById('crud-modal');modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}
async function refreshVisibleData(){await Promise.allSettled([loadDashboard(),state.page==='employee'?loadEmployees():Promise.resolve(),state.page==='training'?loadTraining():Promise.resolve(),state.page==='history'?loadHistory():Promise.resolve(),state.page==='certification'?loadCertification():Promise.resolve(),state.page==='assessment'?loadAssessmentQueue():Promise.resolve(),state.page==='competency'?loadCompetency():Promise.resolve(),state.page==='validation'?loadValidation():Promise.resolve(),state.page==='actions'?loadActions():Promise.resolve(),state.page==='analytics'?loadAnalytics():Promise.resolve()])}
const nullable=v=>v===''?null:v;

async function openEmployeeCreate(){const r=await loadRefs();openCrud('Add Employee',[{name:'employee_code',label:'Employee ID',required:true},{name:'employee_name',label:'Employee Name',required:true},{name:'position_id',label:'Position',type:'select',required:true,options:optionsHtml(r.positions,'position_id',x=>`${x.position_name}${x.department?' — '+x.department:''}`)},{name:'department',label:'Department (optional)'},{name:'join_date',label:'Join Date',type:'date'},{name:'employment_status',label:'Employment Status',type:'select',required:true,options:'<option>Active</option><option>Contract</option>'},{name:'remarks',label:'Remarks',type:'textarea'}],async o=>jsonApi('/api/employees','POST',{...o,position_id:Number(o.position_id),join_date:nullable(o.join_date)}),{note:'Employee baru akan berstatus Pending Initial Assessment. Sistem tidak langsung membuat Potential Gap.'})}
async function openEmployeeEdit(id){const x=state.employeeData.find(r=>Number(r.employee_pk)===Number(id));if(!x)return;openCrud('Edit Employee',[{name:'employee_name',label:'Employee Name',required:true,value:x.employee_name},{name:'department',label:'Department',value:x.department},{name:'join_date',label:'Join Date',type:'date',value:x.join_date},{name:'employment_status',label:'Employment Status',type:'select',required:true,options:['Active','Contract','Resigned','Contract End','Retired','Inactive'].map(v=>`<option ${v===x.employment_status?'selected':''}>${v}</option>`).join('')},{name:'exit_date',label:'Exit Date',type:'date',value:x.exit_date},{name:'status_reason',label:'Status Reason',value:x.status_reason},{name:'remarks',label:'Remarks',type:'textarea',value:x.remarks}],async o=>jsonApi(`/api/employees/${id}`,'PUT',{...o,join_date:nullable(o.join_date),exit_date:nullable(o.exit_date)}))}
async function openPositionChange(id){const x=state.employeeData.find(r=>Number(r.employee_pk)===Number(id));const r=await loadRefs();openCrud(`Change Position — ${x?.employee_name||''}`,[{name:'position_id',label:'New Position',type:'select',required:true,options:optionsHtml(r.positions,'position_id',p=>`${p.position_name}${p.department?' — '+p.department:''}`)},{name:'effective_date',label:'Effective Date',type:'date',required:true,value:new Date().toISOString().slice(0,10)},{name:'change_reason',label:'Reason',type:'select',required:true,options:'<option>Position Change</option><option>Promotion</option><option>Rotation</option><option>Transfer</option><option>Other</option>'},{name:'remarks',label:'Remarks',type:'textarea'}],async o=>jsonApi(`/api/employees/${id}/position-change`,'POST',{...o,position_id:Number(o.position_id)}),{note:'Perubahan posisi akan menandai employee sebagai Pending Reassessment.'})}
function openEmployeeDeactivate(id){const x=state.employeeData.find(r=>Number(r.employee_pk)===Number(id));openCrud(`Deactivate — ${x?.employee_name||''}`,[{name:'effective_date',label:'Effective Date',type:'date',required:true,value:new Date().toISOString().slice(0,10)},{name:'employment_status',label:'Employment Status',type:'select',required:true,options:'<option>Resigned</option><option>Contract End</option><option>Retired</option><option>Inactive</option>'},{name:'reason',label:'Reason',type:'select',required:true,options:'<option>Resignation</option><option>Contract End</option><option>Retirement</option><option>Other</option>'},{name:'remarks',label:'Remarks',type:'textarea'}],async o=>jsonApi(`/api/employees/${id}/deactivate`,'POST',o),{note:'Data tidak dihapus. Employee dipindahkan ke status historical/archived.',submit:'Deactivate'})}
async function openEmployeePurge(id){
  const x=state.employeeData.find(r=>Number(r.employee_pk)===Number(id));if(!x)return;
  try{
    const d=await api(`/api/employees/${id}/purge-impact`);
    if(!d.eligible){showToast('Permanent delete hanya tersedia untuk Employee ID UAT-, TEST-, atau DUMMY-. Gunakan Deactivate untuk employee perusahaan.','error');return}
    const impact=Object.entries(d.impact||{}).filter(([,v])=>Number(v)>0).map(([k,v])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><strong>${esc(v)}</strong></div>`).join('')||'<div><span>Related records</span><strong>0</strong></div>';
    openCrud(`Delete Test Employee — ${x.employee_name}`,[
      {name:'employee_view',label:'Employee',type:'display',value:`${x.employee_code} — ${x.employee_name}`,wide:true},
      {name:'impact_view',label:`Records to remove (${d.related_records||0})`,type:'html',wide:true,html:`<div class="purge-impact">${impact}</div>`},
      {name:'reason',label:'Deletion Reason',type:'textarea',required:true,value:'UAT/test data cleanup'},
      {name:'confirmation_code',label:`Type Employee ID: ${x.employee_code}`,required:true,placeholder:x.employee_code}
    ],async o=>jsonApi(`/api/employees/${id}/purge`,'DELETE',{reason:o.reason,confirmation_code:o.confirmation_code}),{
      note:'Khusus data test. Sistem membuat safety backup lebih dahulu, lalu menghapus employee beserta record turunannya. Evidence dipindahkan ke area recovery backup.',
      submit:'Permanently Delete Test Data'
    });
  }catch(e){showToast(e.message,'error')}
}

