function makeEvidence(d){const all=[];for(const obj of Object.values(d.results||{})){for(const rec of (obj.records||[]))all.push(rec)}if(!all.length)return '';const rows=all.map(r=>{const evidence=r.title||r.certification_name||r.training_name||r.certification_candidate||'—';const status=r.closure_readiness||r.fulfillment_status||r.history_result||r.display_status||r.coverage_status||r.status||'—';const detail=r.due_date?`Due: ${r.due_date}`:r.expired_date?`Expiry Date: ${r.expired_date}`:r.position_name||r.position_standard||r.position_tna||'—';return `<tr><td>${esc(r.employee_name||r.employee||'—')}</td><td>${esc(evidence)}</td><td>${esc(status)}</td><td>${esc(detail)}</td></tr>`}).join('');return `<div class="evidence-box"><details><summary>Lihat record sumber (${esc(all.length)} record)</summary><div class="table-wrap" style="margin-top:8px;max-height:420px"><table><thead><tr><th>Employee</th><th>Record</th><th>Status</th><th>Detail</th></tr></thead><tbody>${rows}</tbody></table></div></details></div>`}
async function exportAI(question,btn){const old=btn.textContent;btn.disabled=true;btn.textContent='Menyiapkan Excel…';try{const r=await fetch('/api/ai/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,conversation_id:state.aiConversationId})});if(!r.ok)throw new Error(await r.text());const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ai_assistant_result.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){alert('Export gagal: '+e.message)}finally{btn.disabled=false;btn.textContent=old}}
async function sendAI(question){const log=document.getElementById('chat-log');log.insertAdjacentHTML('beforeend',`<div class="msg user">${esc(question)}</div><div class="msg assistant" id="typing">Mencari data yang relevan…</div>`);log.scrollTop=log.scrollHeight;try{const d=await api('/api/ai/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,conversation_id:state.aiConversationId})});state.aiConversationId=d.conversation_id||state.aiConversationId;document.getElementById('typing')?.remove();const response=esc(d.response||'Tidak ada respons.').replace(/\n/g,'<br>');const source={training_history:'Training History',training_fulfillment:'Training Fulfillment',training_requirement:'Training Requirement',certification:'Certification',competency:'Competency',action:'Action Center'}[d.source_domain]||'Data sistem';const summaryView=makeSingleDomainSummary(d)||makeDecisionSummary(d);const html=`<div>${response}</div><div class="meta-line">Sumber: ${esc(source)} · ${esc(d.evidence_total ?? d.result_count ?? 0)} record</div>${summaryView}${makeEvidence(d)}<div style="margin-top:10px"><button class="chip" onclick='exportAI(${JSON.stringify(question)},this)'>⬇ Export hasil ke Excel</button></div>`;log.insertAdjacentHTML('beforeend',`<div class="msg assistant">${html}</div>`)}catch(e){document.getElementById('typing')?.remove();log.insertAdjacentHTML('beforeend',`<div class="msg assistant"><strong>Terjadi kesalahan.</strong><div class="meta-line">${esc(e.message)}</div></div>`)}log.scrollTop=log.scrollHeight}
async function resetAIContext(){const old=state.aiConversationId;try{await jsonApi('/api/ai/query','POST',{question:'hapus konteks',conversation_id:old,reset_context:true})}catch{}state.aiConversationId=globalThis.crypto?.randomUUID?globalThis.crypto.randomUUID():String(Date.now());document.getElementById('chat-log').innerHTML='<div class="msg assistant"><strong>Percakapan baru</strong><div>Konteks sebelumnya sudah dihapus. Silakan mulai pertanyaan baru.</div></div>';document.getElementById('ai-input')?.focus()}
