async function validateImport(){const f=document.getElementById('data-file').files[0];const dataset=document.getElementById('dataset-type').value;const box=document.getElementById('import-result');if(!f){box.className='notice';box.textContent='Pilih file Excel terlebih dahulu.';return}const form=new FormData();form.append('file',f);const btn=document.getElementById('validate-import-btn');btn.disabled=true;btn.textContent='Validating…';state.safeImportBatch=null;document.getElementById('confirm-import-panel').classList.add('hidden');document.getElementById('import-preview-card').classList.add('hidden');try{const r=await fetch('/api/data-management/import/validate?dataset_type='+encodeURIComponent(dataset),{method:'POST',body:form});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Validation gagal');box.className='notice';box.textContent=`Validation selesai. Valid ${d.rows_valid}, Warning ${d.rows_warning}, Duplicate ${d.rows_duplicate}, Rejected ${d.rows_rejected}. Database belum berubah.`;renderImportPreview(d);await loadData()}catch(e){box.className='notice';box.textContent='Validation gagal: '+e.message}finally{btn.disabled=false;btn.textContent='Validate File'}}
