  await openActionCreate({employee_pk:employeePk,requirement_id:requirementId,action_type:type,priority:x.priority||'Medium',title:`${type} — ${x.training_name||'Requirement'}`,recommendation:x.decision_action||'',source_decision_id:x.decision_id||null});
