async function loadActions(){
  try{
    await loadWorkflowRefs();
    const p=new URLSearchParams({limit:'5000'}); const st=document.getElementById('action-status-filter')?.value||'',pr=document.getElementById('action-priority-filter')?.value||'',pc=document.getElementById('action-pic-filter')?.value||'',deleted=document.getElementById('action-deleted-filter')?.value||'active';
    p.set('deleted',deleted);if(st)p.set('status',st);if(pr)p.set('priority',pr);if(pc)p.set('pic_user_id',pc);
    const [rows,summary]=await Promise.all([api('/api/actions?'+p.toString()),api('/api/actions/summary')]);state.actions=rows;
    const bs=summary.by_status||{};document.getElementById('action-summary').innerHTML=[['Open',bs.Open||0],['In Progress',(bs['In Progress']||0)+(bs.Scheduled||0)+(bs.Planned||0)+(bs['Waiting Evidence']||0)+(bs['Waiting External Party']||0)],['Awaiting Closure',bs.Completed||0],['Closed',bs.Closed||0],['Overdue',summary.overdue||0],['Unassigned',summary.unassigned||0]].map(([l,v])=>`<div class="kpi"><div class="label">${esc(l)}</div><div class="value">${esc(v)}</div></div>`).join('');
    document.getElementById('action-body').innerHTML=rows.map(a=>`<tr class="${Number(a.is_deleted)?'row-archived':''}"><td><strong>${esc(a.employee_name)}</strong><span class="sub">${esc(a.position_name||'—')}</span></td><td><strong>${esc(a.training_name||a.title)}</strong><span class="sub">${Number(a.is_deleted)?`Deleted: ${esc(a.deletion_reason||'—')}`:esc(a.title)}</span></td><td>${esc(a.action_type)}</td><td>${tag(a.priority)}</td><td>${esc(a.pic_name||'Unassigned')}</td><td>${esc(a.due_date||'—')}${!Number(a.is_deleted)&&a.days_remaining!==''&&a.days_remaining!==null?`<span class="sub ${Number(a.days_remaining)<0?'text-danger':''}">${Number(a.days_remaining)<0?Math.abs(Number(a.days_remaining))+'d overdue':a.days_remaining+'d remaining'}</span>`:''}</td><td>${Number(a.is_deleted)?tag('Deleted'):tag(a.status)}</td><td>${esc(a.evidence_count||0)} file</td><td>${can('action_manage')?(Number(a.is_deleted)?`<button class="mini-btn" onclick="openActionRestore(${Number(a.action_id)})">Restore</button>`:`<button class="mini-btn" onclick="openActionManage(${Number(a.action_id)})">Manage</button>`):'<span class="sub">View only</span>'}</td></tr>`).join('')||'<tr><td colspan="9">Belum ada action record.</td></tr>';
  }catch(e){document.getElementById('action-body').innerHTML=`<tr><td colspan="9">${esc(e.message)}</td></tr>`}
}
async function uploadActionEvidence(actionId,o){const f=o.evidence_file;if(f instanceof File&&f.size){const fd=new FormData();fd.append('entity_type','action');fd.append('entity_id',String(actionId));fd.append('document_type',o.document_type||'Other');fd.append('description',o.evidence_description||'');fd.append('file',f);const r=await fetch('/api/evidence/upload',{method:'POST',body:fd});const x=await r.json();if(!r.ok)throw new Error(x.detail||'Evidence upload gagal')}}
function actionEvidenceHtml(rows=[]){if(!rows.length)return '<div class="existing-evidence-empty">No evidence uploaded yet.</div>';return `<div class="existing-evidence-list">${rows.map(x=>`<div class="existing-evidence-item"><div><strong>${esc(x.original_filename||'Evidence')}</strong><span>${esc(x.document_type||'Other')} · ${esc(x.uploaded_at||'—')}${x.uploaded_by_name?` · by ${esc(x.uploaded_by_name)}`:''}</span></div><div class="row-actions">${Number(x.viewable)?`<button type="button" class="mini-btn" onclick="window.open('/api/evidence/${Number(x.document_id)}/view','_blank','noopener')">View</button>`:''}<button type="button" class="mini-btn" onclick="window.location.href='/api/evidence/${Number(x.document_id)}/download'">Download</button></div></div>`).join('')}</div>`}
function actionEvidenceField(rows=[]){return {name:'existing_evidence',label:`Existing Evidence (${rows.length})`,type:'html',wide:true,html:actionEvidenceHtml(rows)}}
function bindNoActionReason(){const form=document.getElementById('crud-form'),status=form?.elements?.progress_status,reason=form?.elements?.no_action_reason,field=form?.querySelector('[data-field="no_action_reason"]');if(!status||!reason||!field)return;const sync=()=>{const show=status.value==='No Action Required';field.classList.toggle('hidden',!show);reason.required=show};status.addEventListener('change',sync);sync()}
function actionUpdatePayload(a,o,status){return {status,pic_user_id:o.pic_user_id!==undefined?(o.pic_user_id||null):(a.pic_user_id||null),due_date:o.due_date!==undefined?(o.due_date||null):(a.due_date||null),priority:o.priority||a.priority,remarks:o.remarks||null,no_action_reason:o.no_action_reason||a.no_action_reason||null}}
async function finishActionModal(msg='Action berhasil diperbarui.'){closeCrud();showToast(msg);await refreshVisibleData()}
async function openActionReopen(actionId,a){openCrud(`Reopen Action #${actionId}`,[{name:'reason',label:'Reopen Reason',type:'textarea',required:true}],async o=>{await jsonApi(`/api/actions/${actionId}`,'PUT',{status:'Open',pic_user_id:a.pic_user_id||null,due_date:a.due_date||null,priority:a.priority,remarks:o.reason,no_action_reason:a.no_action_reason||null})},{note:'Action yang sudah Closed bersifat read-only. Reopen membuat lifecycle aktif baru dan alasan disimpan pada history.',submit:'Reopen Action'})}
function actionDeleteExtra(actionId,a){return {label:'Delete Action',className:'danger',onClick:async()=>{closeCrud();openActionDelete(actionId,a)}}}
function openActionDelete(actionId,a){openCrud(`Delete Action #${actionId}`,[{name:'reason',label:'Deletion Reason',type:'textarea',required:true,placeholder:'Contoh: UAT/test data atau duplikat'}],async o=>jsonApi(`/api/actions/${actionId}`,'DELETE',{reason:o.reason}),{note:`${a.employee_name||'Employee'} · ${a.title||a.training_name||'Action'}. Action akan disembunyikan dari operasi dan laporan. Evidence tetap tersimpan untuk audit dan dapat dipulihkan melalui filter Deleted / Archived.`,submit:'Confirm Delete'})}
function openActionRestore(actionId){const a=state.actions.find(x=>Number(x.action_id)===Number(actionId))||{};openCrud(`Restore Action #${actionId}`,[{name:'reason',label:'Restore Reason',type:'textarea',required:true,placeholder:'Alasan pemulihan action'}],async o=>jsonApi(`/api/actions/${actionId}/restore`,'POST',{reason:o.reason}),{note:`${a.employee_name||'Employee'} · ${a.title||'Action'}. Action dan evidence terkait akan kembali ke tampilan operasional.`,submit:'Restore Action'})}
async function openActionManage(actionId){
  await loadWorkflowRefs(); const d=await api(`/api/actions/${actionId}`),a=d.action; const status=String(a.status||'Open');
  const note=`${a.employee_name} · ${a.training_name||a.title} | Current status: ${status} | Evidence: ${(d.evidence||[]).length} file | Closure readiness: ${d.completion_readiness?.ready?'READY':'NOT READY'} — ${d.completion_readiness?.reason||''}`;
  const evidenceField=actionEvidenceField(d.evidence||[]);
  if(status==='Closed'){
    openCrud(`Action #${actionId} — Closed`,[{name:'status_view',label:'Status',type:'display',value:'Closed'},{name:'priority_view',label:'Priority',type:'display',value:a.priority},{name:'pic_view',label:'PIC',type:'display',value:a.pic_name||'Unassigned'},{name:'due_view',label:'Due Date',type:'display',value:a.due_date||'—'},{name:'closed_view',label:'Closed At',type:'display',value:a.closed_at||'—'},{name:'remarks_view',label:'Remarks',type:'display',wide:true,value:a.remarks||'—'},evidenceField],async()=>{}, {note:'Closed adalah status terminal dan record ini read-only. Gunakan Reopen Action hanya jika tindak lanjut memang harus dibuka kembali.',hideSubmit:true,extraActions:[{label:'Reopen Action',className:'primary',onClick:async()=>{closeCrud();await openActionReopen(actionId,a)}},actionDeleteExtra(actionId,a)]});return;
  }
  if(['Cancelled','No Action Required'].includes(status)){
    openCrud(`Action #${actionId} — ${status}`,[{name:'status_view',label:'Status',type:'display',value:status},{name:'priority_view',label:'Priority',type:'display',value:a.priority},{name:'pic_view',label:'PIC',type:'display',value:a.pic_name||'Unassigned'},{name:'due_view',label:'Due Date',type:'display',value:a.due_date||'—'},{name:'reason_view',label:'Reason',type:'display',wide:true,value:a.no_action_reason||a.remarks||'—'},evidenceField],async()=>{}, {note:'Status ini bersifat terminal pada workflow saat ini.',hideSubmit:true,extraActions:[actionDeleteExtra(actionId,a)]});return;
  }
  const base=[{name:'priority',label:'Priority',type:'select',required:true,options:valueOptions(state.actionMeta.priorities,a.priority)},{name:'pic_user_id',label:'PIC',type:'select',options:picOptions(a.pic_user_id||'')},{name:'due_date',label:'Due Date',type:'date',value:a.due_date||''}];
  const evidenceUpload=[{name:'evidence_file',label:'Attach Evidence (optional)',type:'file'},{name:'document_type',label:'Evidence Type',type:'select',options:'<option>Certificate</option><option>Training Attendance</option><option>Training Completion Record</option><option>Official Memo</option><option>Validation Document</option><option>Other</option>'},{name:'evidence_description',label:'Evidence Description',value:''}];
  const common=[...base,{name:'remarks',label:'Update Remarks',type:'textarea',value:a.remarks||''},evidenceField,...evidenceUpload];
  if(status==='Completed'){
    const closeReady=!!d.completion_readiness?.ready;
    openCrud(`Action #${actionId} — Awaiting Closure`,common,async o=>{await jsonApi(`/api/actions/${actionId}`,'PUT',actionUpdatePayload(a,o,'Completed'));await uploadActionEvidence(actionId,o)},{note:`${note} | Pekerjaan sudah Completed; status ini menunggu verifikasi/closure.`,submit:'Save Awaiting Closure',extraActions:[{label:'Close Action',className:'primary',disabled:!closeReady,title:closeReady?'Closure readiness READY':`Close dinonaktifkan: ${d.completion_readiness?.reason||'evidence belum siap.'}`,onClick:async o=>{await uploadActionEvidence(actionId,o);await jsonApi(`/api/actions/${actionId}`,'PUT',actionUpdatePayload(a,o,'Closed'));await finishActionModal('Action berhasil di-Closed.') }},actionDeleteExtra(actionId,a)]});return;
  }
  const progress=['Open','Planned','Scheduled','In Progress','Waiting Evidence','Waiting External Party','Cancelled','No Action Required'];
  const fields=[{name:'progress_status',label:'Progress Status',type:'select',required:true,options:valueOptions(progress,status)},...base,{name:'no_action_reason',label:'No Action Reason',value:a.no_action_reason||''},{name:'remarks',label:'Update Remarks',type:'textarea',value:a.remarks||''},evidenceField,...evidenceUpload];
  openCrud(`Manage Action #${actionId}`,fields,async o=>{await jsonApi(`/api/actions/${actionId}`,'PUT',actionUpdatePayload(a,o,o.progress_status));await uploadActionEvidence(actionId,o)},{note:`${note} | Completed dan Closed diproses melalui tombol terpisah agar lifecycle tidak tercampur dengan progress.`,submit:'Save Progress',extraActions:[{label:'Mark Completed',className:'primary',onClick:async o=>{await jsonApi(`/api/actions/${actionId}`,'PUT',actionUpdatePayload(a,o,'Completed'));await uploadActionEvidence(actionId,o);await finishActionModal('Action ditandai Completed dan menunggu Closure.') }},actionDeleteExtra(actionId,a)]});
  bindNoActionReason();
}
