async function loadSystem(){if(!can('backup_manage'))return;try{const [users,backups]=await Promise.all([api('/api/system/users'),api('/api/system/backups?limit=50')]);document.getElementById('system-user-body').innerHTML=users.map(u=>`<tr><td><strong>${esc(u.display_name)}</strong><span class="sub">${esc(u.username||'—')}</span></td><td>${tag(u.role_label||u.role)}</td><td>${tag(Number(u.active_flag)?'Active':'Inactive')}</td><td>${esc(u.last_login_at||'—')}</td><td>${Number(u.must_change_password)?'<span class="tag tag-amber">Password Change Required</span>':'<span class="tag tag-green">Password Set</span>'}</td><td>${Number(u.active_flag)?`<button class="mini-btn" onclick="resetUserPassword('${esc(u.user_id)}')">Reset Password</button>${u.user_id!==state.auth?.user?.user_id?` <button class="mini-btn danger" onclick="deactivateUser('${esc(u.user_id)}')">Deactivate</button>`:''}`:'<span class="sub">Historical</span>'}</td></tr>`).join('');document.getElementById('backup-body').innerHTML=backups.map(b=>`<tr><td><div class="backup-name"><strong>${esc(b.filename)}</strong><small>${esc(b.build||'—')}</small></div></td><td>${tag(b.label||'—')}</td><td>${esc(b.created_at||b.modified_at||'—')}</td><td>${esc(b.created_by||'—')}</td><td>${esc(b.evidence_file_count??'—')}</td><td>${fmtBytes(b.size)}</td><td><button class="mini-btn" onclick="downloadBackup('${esc(b.filename)}')">Download</button> <button class="mini-btn danger" onclick="restoreBackupPrompt('${esc(b.filename)}')">Restore</button></td></tr>`).join('')||'<tr><td colspan="7">Belum ada runtime backup.</td></tr>'}catch(e){showToast(e.message,'error')}}
