document.getElementById('notification-close')?.addEventListener('click',()=>toggleNotificationPanel(false));
document.getElementById('notification-refresh')?.addEventListener('click',refreshNotifications);

document.getElementById('profile-close')?.addEventListener('click',closeEmployeeProfile);document.getElementById('employee-profile')?.addEventListener('click',e=>{if(e.target.id==='employee-profile')closeEmployeeProfile()});document.querySelectorAll('[data-profile-tab]').forEach(b=>b.addEventListener('click',()=>renderEmployeeProfileTab(b.dataset.profileTab)));document.getElementById('profile-export')?.addEventListener('click',profileExport);
const gs=document.getElementById('global-search');gs?.addEventListener('input',()=>{clearTimeout(state.globalSearchTimer);state.globalSearchTimer=setTimeout(runGlobalSearch,250)});gs?.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('global-search-results').classList.add('hidden')});document.addEventListener('click',e=>{if(!e.target.closest('.topbar-search-wrap'))document.getElementById('global-search-results')?.classList.add('hidden')});
document.getElementById('analytics-refresh-btn')?.addEventListener('click',loadAnalytics);document.getElementById('analytics-department')?.addEventListener('change',loadAnalytics);document.getElementById('analytics-snapshot-btn')?.addEventListener('click',refreshAnalyticsSnapshot);document.getElementById('analytics-export-btn')?.addEventListener('click',exportManagementReport);
document.getElementById('login-form')?.addEventListener('submit',handleLogin);document.getElementById('password-form')?.addEventListener('submit',handlePasswordChange);document.getElementById('logout-btn')?.addEventListener('click',doLogout);document.getElementById('change-password-btn')?.addEventListener('click',openChangePassword);document.getElementById('backup-now-btn')?.addEventListener('click',createBackupNow);document.getElementById('backup-refresh-btn')?.addEventListener('click',loadSystem);document.getElementById('user-add-btn')?.addEventListener('click',openUserCreate);bootstrapAuth();
